import { Events } from 'discord.js';
import config from '../config.json' with { type: 'json' };
const enableGMChanceImprovement = config.enableGMChanceImprovement;
import path from 'path';

export default {
    type: Events.InteractionCreate,
    name: path.basename(import.meta.url, '.js'),
    async execute(interaction, character, client) {
        if (!interaction.isChatInputCommand()) return;
        if (interaction.commandName === path.basename(import.meta.url, '.js')) {
            const utils = client.Common;
            let wuerfel = interaction.options.getString('würfel') ?? 0;

            const parsedRoll = utils.parseWuerfel(wuerfel);
            let result = utils.wuerfelWerfen(wuerfel);
            console.log({ originalResult: result })
            if (result.notation.endsWith('d20') && enableGMChanceImprovement && interaction?.isMeister()) {
                var rand = Math.random();
                var randRange = (Math.floor(rand * 100) + 1);
                var improveMeisterChance = randRange <= (character?.cheating?.general ?? 40);
                console.log(`to cheat prop: ${`${randRange}`.yellow}, cheat on hit: ${`${improveMeisterChance === true}`.yellow}`);
                console.log(`Original Dice Result: ${result}`);
                console.log("Character cheating options: ", character.cheating);

                if (improveMeisterChance === true) {
                    result.rolls.forEach(function (roll, index) {
                        var isCrit = (Math.floor(Math.random() * 100) + 1) <= (character?.cheating?.crit ?? 15);
                        console.log(`orig: ${`${roll}`.yellow}, isCrit: ${`${isCrit}`.yellow}`)
                        this[index] = isCrit === true ? 1 : roll <= 5 ? roll : roll - 3;
                    }, result.rolls);
                    result.value = result.rolls.reduce((a, b) => a + b)
                    console.log({ finalResult: result })
                }
            }

            let event = {
                type: "event",
                name: "roll",
                parsedRoll,
                result
            };

            let embed = {
                title: `Würfelergebnis von ${event.parsedRoll} durch ${character.displayName ?? character.name}!`,
                color: 0x0099ff,
                fields: [
                    { name: 'Ergebnis', value: `${event.result.value}`, inline: false },
                    { name: 'Würfelwurf', value: `${event.result.rolls.join(', ')}`, inline: false }
                ]
            }

            await interaction.reply({ embeds: [embed] });

            return [event];

        }
    }
};

import { Character } from './common/character.js';
import fs from 'node:fs';
import path from 'node:path';
import { Client, Collection, GatewayIntentBits } from 'discord.js';
import configJson from './config.json' with { type: 'json' };
import { EventEmitter } from 'node:events';
import { persistCharacter, retrieveCharacter } from './common/persistence.js';

const token = configJson.token;
const emitter = new EventEmitter();
emitter.setMaxListeners(0);

// Hilfsfunktion für __dirname in ES Modules
const __dirname = path.dirname(new URL(import.meta.url).pathname);

// Create a new client instance
const client = new Client({ intents: [GatewayIntentBits.Guilds] });
client.commands = new Collection();
client.histories = {};

const commandsPath = path.join(__dirname, 'commands');
const commandFiles = fs.readdirSync(commandsPath).filter(file => file.endsWith('.js'));

for (const file of commandFiles) {
    const filePath = path.join(commandsPath, file);
    const commandModule = await import(filePath);
    const command = commandModule.default || commandModule;
    client.commands.set(command.data.name, command);
}

const eventsPath = path.join(__dirname, 'events');
const eventFiles = fs.readdirSync(eventsPath).filter(file => file.endsWith('.js'));

for (const file of eventFiles) {
    const filePath = path.join(eventsPath, file);
    const eventModule = await import(filePath);
    const event = eventModule.default || eventModule;

    if (event.once) {
        client.once(event.name, (...args) => event.execute(...args));
    } else {
        client.on(event.name, async (...args) => {
            console.log(`exec ${event.name}`);
            let char = getChar(...args);
            let events = await log(event.execute, event, args, char, client);
            if (events && ((events instanceof Array) || events?.type === "event")) {
                client.histories[char.name] = client.histories[char.name] ?? [];
                client.histories[char.name].push(...events)
            }
        });
    }
}

async function log(func, event, args, character, client) {
    let result = await func(...args, character, client);
    return result;
}

client.characters = new Collection();
client.characterConfig = (await import(path.join(__dirname, 'chars', 'config.json'), { assert: { type: 'json' } })).default;
const charsPath = path.join(__dirname, 'chars');
const charsFiles = fs.readdirSync(charsPath).filter(file => file.endsWith('.json') && file !== "config.json");

for (const file of charsFiles) {
    const filePath = path.join(charsPath, file);
    const characterModule = await import(filePath, { assert: { type: 'json' } });
    const character = characterModule.default || characterModule;
    client.characters.set(character.name, new Character(character));
    retrieveCharacter(character.name).then(persistenceChar => {
        let c = new Character(persistenceChar);
        if (persistenceChar) {
            persistenceChar.angelegteWaffen = persistenceChar.angelegteWaffen ?? [];
            client.characters.set(persistenceChar.name, new Character(persistenceChar));
        }
        else {
            character.angelegteWaffen = character.angelegteWaffen ?? [];
            persistCharacter(character);
        }
    });
}

// Login to Discord with your client's token
client.login(token);

const getChar = (interaction) => {
    let charname = client.characterConfig.alias[interaction.user.username].toLowerCase();
    let char = client.characters.find(c => c.name.toLowerCase() === charname);
    return char;
};
